28	async function expectApiError(
29	  call: Promise<unknown>,
30	  status: number,
31	  code: string,
32	  message?: string,
33	) {
34	  // oxlint-disable-next-line typescript/await-thenable -- bun's `rejects` is typed as void
35	  await expect(call).rejects.toBeInstanceOf(PaymentsApiError);
36	  // oxlint-disable-next-line typescript/await-thenable -- bun's `rejects` is typed as void
37	  await expect(call).rejects.toMatchObject({
38	    name: "PaymentsApiError",
39	    status,
40	    code,
41	    ...(message !== undefined && { message }),
42	  });
43	}
